package edu.demo.exam.util;
import edu.demo.exam.model.*;
public final class TimetableValidator {private TimetableValidator(){} public static void requireValid(ConflictGraph g,int r,Timetable t){String error=validate(g,r,t);if(error!=null)throw new IllegalStateException("Invalid timetable: "+error);} public static String validate(ConflictGraph g,int r,Timetable t){if(r<1)return "capacity must be positive";int[] a=t.assignments();if(a.length!=g.size())return "course count does not match graph";int slots=t.slotCount();int[] counts=new int[slots];for(int x=0;x<a.length;x++){if(a[x]<0||a[x]>=slots)return "course "+(x+1)+" has invalid slot";if(++counts[a[x]]>r)return "slot "+(a[x]+1)+" exceeds hall capacity";for(int y:g.neighbours(x+1))if(y>x&&a[x]==a[y])return "conflicting courses "+(x+1)+" and "+(y+1)+" share a slot";}for(int c:counts)if(c==0)return "slot numbering has a gap";return null;}}
